class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        if not s:
            return 0

        n = len(s)
        # Count frequency of each character
        char_counts = {}
        for c in s:
            if c in char_counts:
                char_counts[c] += 1
            else:
                char_counts[c] = 1

        # Use sliding window approach
        max_len = 0

        for i in range(n):
            # Expand window by adding character at i
            window = set()
            for j in range(i, n):
                if s[j] in window:
                    window.add(s[j])
                else:
                    break

            # Check if window contains at most 2 occurrences of each character
            # Count character frequencies
            char_freq = {}
            for c in window:
                char_freq[c] = char_counts[c] - 1
            # Check if all counts are <= 2
            if all(count <= 2 for count in char_freq.values()):
                max_len = max(max_len, len(window))

        return max_len
