import sys

def solve():
    # Read N
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = []
    # Read the N integers
    # Since the input is split by whitespace, we can just take the next N elements
    for i in range(n):
        a.append(int(input_data[i+1]))

    # Calculate B_i = A_i * A_{i+1}
    # We need to print B_1 to B_{N-1}
    results = []
    for i in range(n - 1):
        results.append(a[i] * a[i+1])

    # Print results separated by spaces
    print(*(results))

if __name__ == "__main__":
    solve()
