import sys

def solve():
    try:
        input = sys.stdin.read
        data = input().split()
    except Exception:
        return

    # Parse N
    iterator = iter(data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    # Parse grids
    A = []
    B = []

    for i in range(N):
        row = []
        for j in range(N):
            row.append(next(iterator))
        A.append(row)

    # Compare row by row and column by column
    for i in range(N):
        for j in range(N):
            if A[i][j] != B[i][j]:
                print(f"{i+1} {j+1}")
                return

if __name__ == "__main__":
    solve()
